package com.portfolio.features.portfolio.service; import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import com.portfolio.common.exception.ConflictException; import com.portfolio.features.portfolio.dto.*; import com.portfolio.features.portfolio.entity.PortfolioSection; import com.portfolio.features.portfolio.repository.PortfolioSectionRepository; import com.portfolio.features.user.entity.AppUser; import java.util.*; import lombok.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service @RequiredArgsConstructor public class PortfolioDesignService {private final PortfolioAccessService access;private final PortfolioSectionRepository sections;private final ObjectMapper json;private static final List<String> DEFAULT=List.of("HERO","ABOUT","PROJECTS","EXPERIENCE","EDUCATION","SKILLS","CONTACT");@Transactional public void design(AppUser u,DesignRequest request){var p=access.mine(u);p.setTemplateKey(request.templateKey());try{p.setThemeConfig(json.writeValueAsString(request.themeConfig()));}catch(JsonProcessingException e){throw new IllegalArgumentException("Theme is invalid.");}}@Transactional public List<SectionResponse> updateSections(AppUser u,SectionRequest request){var p=access.mine(u);var types=new HashSet<String>();for(var item:request.sections())if(!types.add(item.sectionType()))throw new ConflictException("Duplicate section type.");if(!types.contains("HERO"))throw new ConflictException("Hero section is required.");sections.deleteByPortfolioId(p.getId());int pos=1;for(var item:request.sections().stream().sorted(Comparator.comparingInt(SectionRequest.SectionItem::position)).toList()){var s=new PortfolioSection();s.setPortfolio(p);s.setSectionType(item.sectionType());s.setPosition(pos++);s.setEnabled(item.sectionType().equals("HERO")||item.enabled());sections.save(s);}return get(u);}@Transactional(readOnly=true) public List<SectionResponse> get(AppUser u){var p=access.mine(u);var saved=sections.findByPortfolioIdOrderByPositionAsc(p.getId());if(saved.isEmpty())return defaults();return saved.stream().map(s->new SectionResponse(s.getSectionType(),s.getPosition(),s.isEnabled())).toList();}private List<SectionResponse> defaults(){var out=new ArrayList<SectionResponse>();for(int i=0;i<DEFAULT.size();i++)out.add(new SectionResponse(DEFAULT.get(i),i+1,true));return out;}}
